// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPermanentMarker = makeLoadFont('PermanentMarker');

// Load marker-style font at the module level to ensure it's ready before frame 0
const { fontFamily: markerFamily } = loadPermanentMarker();



export type TimelineSignpostsProps = Record<string, any>;

const TimelineSignposts: React.FC<TimelineSignpostsProps> = ({
  backgroundColor = "#f4f4f5",
  transparentBackground = false,
  durationInSeconds = 8,
  timelineColor = "#09090b",
  textColor = "#09090b",
  mainImage = "https://images.unsplash.com/photo-1596496050827-8299e0220de1?q=80&w=400&auto=format&fit=crop",
  signposts = [
    { text: "Discovery" },
    { text: "Strategy" },
    { text: "Execution" },
    { text: "Launch" }
  ]
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation timeline configuration
  const lineStartFrame = 20;
  const lineEndFrame = 140;

  // Interpolate the main timeline connecting line from 0% to 100%
  const lineWidthProgress = interpolate(
    frame,
    [lineStartFrame, lineEndFrame],
    [0, 100],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Traveling image scales up as the timeline starts
  const travelingImgScale = spring({
    fps,
    frame: frame - lineStartFrame,
    config: { damping: 12, mass: 1 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div style={{ position: "absolute", left: "15%", right: "15%", top: 0, bottom: 0 }}>
        
        {/* Timeline Background Track */}
        <div style={{ 
          position: "absolute", 
          left: 0, 
          right: 0, 
          top: "50%", 
          height: 8, 
          transform: "translateY(-50%)", 
          backgroundColor: `${timelineColor}20`, 
          borderRadius: 4 
        }}>
          {/* Timeline Fill Progress */}
          <div style={{ 
            height: "100%", 
            width: `${lineWidthProgress}%`, 
            backgroundColor: timelineColor, 
            borderRadius: 4,
            transition: "none"
          }} />
        </div>

        {/* Signpost Items */}
        {signposts.map((item, index) => {
          // Calculate stagger timing tied exactly to the visual line progress
          const progressFactor = signposts.length > 1 ? index / (signposts.length - 1) : 0.5;
          const leftPos = progressFactor * 100;
          
          // Calculate exact frame the center of the photo (and line) reaches this dot
          const itemCenterTime = lineStartFrame + (lineEndFrame - lineStartFrame) * progressFactor;
          
          // Animate as the photo's edge arrives, but not before the timeline itself starts
          const triggerTime = Math.max(lineStartFrame, itemCenterTime - 8);

          // Animations
          const dotScale = spring({
            fps,
            frame: frame - triggerTime,
            config: { damping: 14, mass: 0.8 },
          });

          const textRevealProgress = interpolate(
            frame,
            [triggerTime, triggerTime + 30],
            [0, 100],
            { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
          );
          
          const textY = interpolate(
            frame,
            [triggerTime, triggerTime + 20],
            [15, 0],
            { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
          );

          return (
            <div 
              key={index} 
              style={{ 
                position: "absolute", 
                left: `${leftPos}%`, 
                top: "50%" 
              }}
            >
              {/* Center Anchor Dot */}
              <div style={{ 
                position: "absolute", 
                left: -14, 
                top: -14, 
                width: 28, 
                height: 28, 
                borderRadius: 14, 
                backgroundColor: timelineColor,
                transform: `scale(${dotScale})`,
                transition: "none",
                boxShadow: "0 4px 12px rgba(0,0,0,0.15)"
              }} />

              {/* Marker Text */}
              <div style={{ 
                position: "absolute", 
                top: 40, 
                left: -200, 
                width: 400, 
                display: "flex", 
                justifyContent: "center" 
              }}>
                <span style={{ 
                  fontFamily: markerFamily, 
                  fontSize: 42, 
                  color: textColor,
                  clipPath: `inset(0 ${100 - textRevealProgress}% 0 0)`,
                  display: "inline-block",
                  whiteSpace: "nowrap",
                  transition: "none",
                  padding: "10px 0",
                  transform: `translateY(${textY}px)`
                }}>
                  {item.text}
                </span>
              </div>
            </div>
          );
        })}

        {/* Traveling Image - Acts as the playhead of the line */}
        <div style={{
          position: "absolute",
          top: "50%",
          left: `${lineWidthProgress}%`,
          transition: "none",
          zIndex: 10
        }}>
          {/* Circle Cropped Image */}
          <div style={{ 
            position: "absolute", 
            bottom: 40, 
            left: -120, 
            width: 240, 
            height: 240, 
            borderRadius: "50%", 
            overflow: "hidden",
            transform: `scale(${travelingImgScale})`,
            transformOrigin: "bottom center",
            transition: "none",
            boxShadow: "0 12px 32px rgba(0,0,0,0.12)",
            backgroundColor: `${timelineColor}10`
          }}>
            {mainImage && (
              <Img 
                src={mainImage} 
                style={{ 
                  width: "100%", 
                  height: "100%", 
                  objectFit: "cover" 
                }} 
              />
            )}
          </div>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default TimelineSignposts;